                    .points_to_directory()
                    .cmp(&a.as_ref().points_to_directory())
            });
        } else if self.flags.contains(&FileFilterFlags::ListDirsLast) {
            files.sort_by(|a, b| {
                a.as_ref()
                    .points_to_directory()
                    .cmp(&b.as_ref().points_to_directory())
            });
        }
    }
